UPDATE vendors SET pickup='{"ru":"Джавахетская улица, Каро — «Фруктовый сад»","hy":"Ջավախքի փողոց, Կարո՝ «Պտղատու այգի»","ka":"ჯავახეთის ქუჩა, კარო — „ხილის ბაღი“"}' WHERE id='akhalkalaki-karo' AND (pickup IS NULL OR pickup<>'{"ru":"Джавахетская улица, Каро — «Фруктовый сад»","hy":"Ջավախքի փողոց, Կարո՝ «Պտղատու այգի»","ka":"ჯავახეთის ქუჩა, კარო — „ხილის ბაღი“"}');
