UPDATE vendors SET pickup='{"ru":"У Пло, чуть ниже по улице Свободы от рынка — магазин Партез","hy":"Պլոյի մոտ, Ազատության փողոցով շուկայից մի փոքր ներքև՝ «Պարտեզ» խանութ","ka":"პლოსთან, თავისუფლების ქუჩაზე ბაზრიდან ოდნავ დაბლა — მაღაზია „პარტეზი“"}' WHERE id='akhalkalaki-artur' AND (pickup IS NULL OR pickup<>'{"ru":"У Пло, чуть ниже по улице Свободы от рынка — магазин Партез","hy":"Պլոյի մոտ, Ազատության փողոցով շուկայից մի փոքր ներքև՝ «Պարտեզ» խանութ","ka":"პლოსთან, თავისუფლების ქუჩაზე ბაზრიდან ოდნავ დაბლა — მაღაზია „პარტეზი“"}');
